319	export function PortalProvider({ children }: { children: React.ReactNode }) {
320	  const [entities, setEntities] = useState<CompanyEntity[]>(INITIAL_ENTITIES);
321	  const [activeEntityId, setActiveEntityId] = useState<string>('ent_01');
322	  const [orders, setOrders] = useState<OrderItem[]>([]);
323	  const [taxRecords, setTaxRecords] = useState<TaxRecord[]>(INITIAL_TAX_RECORDS);
324	  const [expenses, setExpenses] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
325	  const [bankingApps, setBankingApps] = useState<BankingApplication[]>(INITIAL_BANKING_APPS);
326	  const [whatsappLogs, setWhatsappLogs] = useState<WhatsAppNotification[]>(INITIAL_WHATSAPP_LOGS);
327	  const [userProfile, setUserProfile] = useState<UserProfile>(INITIAL_USER_PROFILE);
328	
329	  // Load from local storage on mount
330	  useEffect(() => {
331	    try {
332	      const savedEntities = localStorage.getItem('gcc_entities');
333	      if (savedEntities) setEntities(JSON.parse(savedEntities));
334	      const savedActive = localStorage.getItem('gcc_active_entity');
335	      if (savedActive) setActiveEntityId(savedActive);
336	      const savedOrders = localStorage.getItem('gcc_orders');
337	      if (savedOrders) setOrders(JSON.parse(savedOrders));
338	      const savedTax = localStorage.getItem('gcc_tax_records');
339	      if (savedTax) setTaxRecords(JSON.parse(savedTax));
340	      const savedExpenses = localStorage.getItem('gcc_expenses');
341	      if (savedExpenses) setExpenses(JSON.parse(savedExpenses));
342	      const savedBanking = localStorage.getItem('gcc_banking_apps');
343	      if (savedBanking) setBankingApps(JSON.parse(savedBanking));
344	      const savedWa = localStorage.getItem('gcc_wa_logs');
345	      if (savedWa) setWhatsappLogs(JSON.parse(savedWa));
346	      const savedProfile = localStorage.getItem('gcc_user_profile');
347	      if (savedProfile) setUserProfile(JSON.parse(savedProfile));
348	    } catch (err) {
349	      console.warn('LocalStorage error:', err);
350	    }
351	  }, []);
352	
353	  // Save to local storage on changes
354	  useEffect(() => {
355	    try {
356	      localStorage.setItem('gcc_entities', JSON.stringify(entities));
357	      localStorage.setItem('gcc_active_entity', activeEntityId);
358	      localStorage.setItem('gcc_orders', JSON.stringify(orders));
359	      localStorage.setItem('gcc_tax_records', JSON.stringify(taxRecords));
360	      localStorage.setItem('gcc_expenses', JSON.stringify(expenses));
361	      localStorage.setItem('gcc_banking_apps', JSON.stringify(bankingApps));
362	      localStorage.setItem('gcc_wa_logs', JSON.stringify(whatsappLogs));
363	      localStorage.setItem('gcc_user_profile', JSON.stringify(userProfile));
364	    } catch (err) {
365	      console.warn('LocalStorage save error:', err);
366	    }
367	  }, [entities, activeEntityId, orders, taxRecords, expenses, bankingApps, whatsappLogs, userProfile]);
368	
369	  const updateUserProfile = (updates: Partial<UserProfile>) => {
370	    setUserProfile((prev) => ({ ...prev, ...updates }));
371	  };
372	
373	  const markNotificationRead = (id: string) => {
374	    setWhatsappLogs((prev) =>
375	      prev.map((item) => (item.id === id ? { ...item, status: 'read' } : item))
376	    );
377	  };
378	
379	  const markAllNotificationsRead = () => {
380	    setWhatsappLogs((prev) => prev.map((item) => ({ ...item, status: 'read' })));
381	  };
382	
383	  const createOrderAndEntity = (data: {
384	    companyName: string;
385	    country: string;
386	    tier: 'tier1' | 'tier2' | 'tier3';
387	    totalAmount: number;
388	    chargedNow: number;
389	    clientName: string;
390	    clientEmail: string;
391	    clientWhatsApp: string;
392	    paymentMethod: string;
393	  }) => {
394	    const newOrderId = `ORD-${Date.now().toString().slice(-6)}`;
395	    const newEntityId = `ent_${Date.now().toString().slice(-4)}`;
396	
397	    const countryMap: Record<string, { name: string; code: CompanyEntity['countryCode'] }> = {
398	      uae: { name: 'UAE Freezone (IFZA Dubai)', code: 'uae' },
399	      hk: { name: 'Hong Kong (Offshore Entity)', code: 'hk' },
