1	import { SignJWT, jwtVerify } from 'jose';
2	import { createHash, randomBytes } from 'crypto';
3	
4	const secret = new TextEncoder().encode(
5	  process.env.JWT_SECRET || 'gccstartup-dev-secret'
6	);
7	
8	export interface TokenPayload {
9	  userId: string;
10	  email: string;
11	  role: string;
12	}
13	
14	export async function generateToken(payload: TokenPayload): Promise<string> {
15	  return new SignJWT(payload as unknown as Record<string, unknown>)
16	    .setProtectedHeader({ alg: 'HS256' })
17	    .setIssuedAt()
18	    .setExpirationTime('7d')
19	    .setSubject(payload.userId)
20	    .sign(secret);
21	}
22	
23	export async function verifyToken(
24	  token: string
25	): Promise<TokenPayload | null> {
26	  try {
27	    const { payload } = await jwtVerify(token, secret);
28	    return {
29	      userId: payload.sub as string,
30	      email: payload.email as string,
31	      role: payload.role as string,
32	    };
33	  } catch {
34	    return null;
35	  }
36	}
37	
38	export function hashToken(token: string): string {
39	  return createHash('sha256').update(token).digest('hex');
40	}
41	
42	export function generateMagicToken(): string {
43	  return randomBytes(32).toString('hex');
44	}
