11	export function useSession() {
12	  const [user, setUser] = useState<SessionUser | null>(null);
13	  const [isLoading, setIsLoading] = useState(true);
14	
15	  useEffect(() => {
16	    fetch('/api/auth/session')
17	      .then((res) => {
18	        if (res.ok) return res.json();
19	        return null;
20	      })
21	      .then((data) => {
22	        if (data?.user) {
23	          setUser(data.user);
24	        } else {
25	          setUser(null);
26	        }
27	      })
28	      .catch(() => {
29	        setUser(null);
30	      })
31	      .finally(() => {
32	        setIsLoading(false);
33	      });
34	  }, []);
35	
36	  return { user, isLoading };
37	}
