39	export function getCookie(name: string): string | null {
40	  if (typeof document === 'undefined') return null;
41	  const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
42	  return match ? decodeURIComponent(match[2]) : null;
43	}
44	
45	export function isAuthenticated(): boolean {
46	  return !!getCookie('gcc_session');
47	}
