49	export function isAdmin(): boolean {
50	  const token = getCookie('gcc_session');
51	  if (!token) return false;
52	
53	  try {
54	    const payload = JSON.parse(atob(token.split('.')[1]));
55	    return payload.role === 'admin' || payload.role === 'super_admin';
56	  } catch {
57	    return false;
58	  }
59	}
