1	import { Pool } from '@neondatabase/serverless';
2	
3	const pool = new Pool({ connectionString: process.env.DATABASE_URL });
4	
5	export async function query<T = any>(
6	  text: string,
7	  params?: any[]
8	): Promise<T[]> {
9	  const result = await pool.query(text, params ?? []);
10	  return result.rows as T[];
11	}
12	
13	export async function queryOne<T = any>(
14	  text: string,
15	  params?: any[]
16	): Promise<T | null> {
17	  const rows = await query<T>(text, params);
18	  return rows[0] ?? null;
19	}
20	
21	export async function transaction<T>(
22	  fn: (client: { query: (text: string, params?: any[]) => Promise<any> }) => Promise<T>
23	): Promise<T> {
24	  const client = await pool.connect();
25	  try {
26	    await client.query('BEGIN');
27	    const result = await fn(client);
28	    await client.query('COMMIT');
29	    return result;
30	  } catch (e) {
31	    await client.query('ROLLBACK');
32	    throw e;
33	  } finally {
34	    client.release();
35	  }
36	}
