34	  if (!authHeader?.startsWith('Bearer ')) {
35	    throw new Error('Missing or invalid Authorization header');
36	  }
37	
38	  const token = authHeader.slice(7);
39	  const secret = new TextEncoder().encode(process.env.JWT_SECRET!);
40	
41	  const { payload } = await jwtVerify(token, secret);
42	  const user = payload as unknown as JWTPayload;
43	
44	  if (user.role !== 'admin') {
45	    throw new Error('Insufficient permissions');
46	  }
47	
48	  return user;
49	}
