47	
48	function verifyWebhookSignature(
49	  body: string,
50	  signatureHeader: string | null,
51	  appSecret: string
52	): boolean {
53	  if (!signatureHeader) return false;
54	
55	  // Meta sends x-hub-signature-256: sha256=<hex>
56	  const expectedSignature = `sha256=${createHmac('sha256', appSecret).update(body).digest('hex')}`;
57	
58	  try {
59	    return timingSafeEqual(
60	      Buffer.from(signatureHeader),
61	      Buffer.from(expectedSignature)
62	    );
63	  } catch {
64	    return false;
65	  }
66	}
