67	    const body = await request.text();
68	    const signature = request.headers.get('Stripe-Signature');
69	
70	    if (!signature) {
71	      return NextResponse.json({ error: 'Missing Stripe-Signature header' }, { status: 400 });
72	    }
73	
74	    // 1. Verify webhook signature
75	    let event: Stripe.Event;
76	    try {
77	      event = getStripe().webhooks.constructEvent(body, signature, getWebhookSecret());
78	    } catch (err) {
79	      const message = err instanceof Error ? err.message : 'Webhook verification failed';
80	      console.error('[webhooks/stripe] Signature verification failed:', message);
81	      return NextResponse.json({ error: 'Invalid signature' }, { status: 400 });
82	    }
83	
84	    // 2. Handle checkout.session.completed
85	    if (event.type === 'checkout.session.completed') {
86	      const session = event.data.object as Stripe.Checkout.Session;
87	
88	      const orderId = session.metadata?.order_id;
89	      const companyId = session.metadata?.company_id;
90	
91	      if (!orderId || !companyId) {
92	        console.error('[webhooks/stripe] Missing order_id or company_id in session metadata');
93	        return NextResponse.json({ received: true });
