98	        company_id: companyId,
99	        status: 'paid',
100	        customer_email: session.customer_details?.email ?? '',
101	        customer_phone: session.customer_details?.phone ?? undefined,
102	        amount_total: session.amount_total ?? 0,
103	        currency: session.currency ?? 'usd',
104	      };
