112	      // 4. Transition company status from 'lead' to 'onboarding'
113	      await query(
114	        `UPDATE companies SET status = 'onboarding', updated_at = NOW() WHERE id = $1`,
115	        [companyId]
116	      );
117	
118	      // 5. Generate magic login token and store on user
119	      const magicToken = crypto.randomUUID();
