122	      await query(
123	        `UPDATE users SET magic_token = $1, magic_token_expires_at = $2
124	         WHERE id = (SELECT user_id FROM companies WHERE id = $3)`,
125	        [magicToken, tokenExpiry.toISOString(), companyId]
126	      );
127	
128	      // 6. Dispatch WhatsApp welcome message
129	      if (orderUpdate.customer_phone) {
130	        const company = await queryOne<{ company_name: string }>(
131	          `SELECT company_name FROM companies WHERE id = $1`,
132	          [companyId]
133	        );
134	        const companyName = company?.company_name ?? 'Your Company';
135	        await dispatchWhatsAppWelcome(orderUpdate.customer_phone, companyName, magicToken);
136	      }
137	
138	      console.log(`[webhooks/stripe] Order ${orderId} processed successfully`);
139	    }
140	
141	    return NextResponse.json({ received: true }, { status: 200 });
142	  } catch (error) {
143	    console.error('[webhooks/stripe] Error:', error);
144	    return NextResponse.json(
145	      { error: 'Internal server error' },
