1	import { NextRequest, NextResponse } from 'next/server';
2	import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
3	import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
4	import { jwtVerify } from 'jose';
5	import { query } from '@/lib/db';
6	
7	// ---------------------------------------------------------------------------
8	// Types
9	// ---------------------------------------------------------------------------
10	
11	interface PresignRequest {
12	  company_id: string;
13	  category: string;
14	  file_name: string;
15	  file_size: number;
16	  mime_type: string;
17	}
18	
19	interface PresignResponse {
20	  document_id: string;
21	  upload_url: string;
22	  r2_key: string;
23	  expires_in_seconds: number;
24	}
25	
26	interface JWTPayload {
27	  sub: string;
28	  email: string;
29	  role: string;
30	  company_id?: string;
31	}
32	
33	// ---------------------------------------------------------------------------
34	// R2 / S3 Client
35	// ---------------------------------------------------------------------------
36	
37	const r2Client = new S3Client({
38	  region: 'auto',
39	  endpoint: process.env.R2_ENDPOINT!,
40	  credentials: {
41	    accessKeyId: process.env.R2_ACCESS_KEY_ID!,
42	    secretAccessKey: process.env.R2_SECRET_ACCESS_KEY!,
43	  },
44	});
45	
46	const BUCKET_NAME = process.env.R2_BUCKET_NAME!;
47	const PRESIGN_EXPIRY_SECONDS = 900; // 15 minutes
48	
49	// ---------------------------------------------------------------------------
50	// Auth helper
51	// ---------------------------------------------------------------------------
52	
53	async function verifyAuth(request: NextRequest): Promise<JWTPayload> {
54	  const authHeader = request.headers.get('Authorization');
55	  if (!authHeader?.startsWith('Bearer ')) {
56	    throw new Error('Missing or invalid Authorization header');
57	  }
58	
59	  const token = authHeader.slice(7);
60	  const secret = new TextEncoder().encode(process.env.JWT_SECRET!);
61	
62	  const { payload } = await jwtVerify(token, secret);
63	  return payload as unknown as JWTPayload;
64	}
65	
66	// ---------------------------------------------------------------------------
67	// POST /api/vault/presign
68	// ---------------------------------------------------------------------------
69	
70	export async function POST(request: NextRequest): Promise<NextResponse> {
71	  try {
72	    // 1. Authenticate
73	    let user: JWTPayload;
74	    try {
75	      user = await verifyAuth(request);
76	    } catch {
77	      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
78	    }
79	
80	    // 2. Parse body
81	    const body = (await request.json()) as PresignRequest;
82	    const { company_id, category, file_name, file_size, mime_type } = body;
83	
84	    if (!company_id || !category || !file_name || !file_size || !mime_type) {
85	      return NextResponse.json(
86	        { error: 'Missing required fields: company_id, category, file_name, file_size, mime_type' },
87	        { status: 400 }
88	      );
89	    }
90	
91	    // 3. Validate company access
92	    if (user.role !== 'admin' && user.company_id !== company_id) {
93	      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
94	    }
95	
96	    // 4. Validate file size (max 25 MB)
97	    const MAX_FILE_SIZE = 25 * 1024 * 1024;
98	    if (file_size > MAX_FILE_SIZE) {
99	      return NextResponse.json(
100	        { error: `File size exceeds maximum of ${MAX_FILE_SIZE / 1024 / 1024}MB` },
101	        { status: 400 }
102	      );
103	    }
104	
105	    // 5. Build R2 key
106	    const now = new Date();
107	    const year = now.getFullYear();
108	    const month = String(now.getMonth() + 1).padStart(2, '0');
109	    const safeFileName = file_name.replace(/[^a-zA-Z0-9._-]/g, '_');
110	    const r2Key = `vault/${year}/${month}/${safeFileName}`;
111	
112	    // 6. Create document record in database
113	    const documentId = crypto.randomUUID();
114	
115	    await query(
116	      `INSERT INTO documents (id, company_id, user_id, category, file_name, r2_key, mime_type, file_size_bytes, status, uploaded_by, created_at, updated_at)
117	       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'active', $3, NOW(), NOW())`,
118	      [documentId, company_id, user.sub, category, file_name, r2Key, mime_type, file_size]
119	    );
120	
121	    // 7. Generate presigned PUT URL
122	    const command = new PutObjectCommand({
123	      Bucket: BUCKET_NAME,
124	      Key: r2Key,
125	      ContentType: mime_type,
126	      ContentLength: file_size,
127	    });
128	
129	    const uploadUrl = await getSignedUrl(r2Client, command, {
130	      expiresIn: PRESIGN_EXPIRY_SECONDS,
131	    });
132	
133	    const response: PresignResponse = {
134	      document_id: documentId,
135	      upload_url: uploadUrl,
136	      r2_key: r2Key,
137	      expires_in_seconds: PRESIGN_EXPIRY_SECONDS,
138	    };
139	
140	    return NextResponse.json(response, { status: 200 });
141	  } catch (error) {
142	    console.error('[vault/presign] Error:', error);
143	    return NextResponse.json(
144	      { error: 'Internal server error' },
145	      { status: 500 }
146	    );
147	  }
148	}
