146	export function verifyWebhookSignature(body: string, signature: string): boolean {
147	  try {
148	    const appSecret = process.env.WHATSAPP_APP_SECRET;
149	    if (!appSecret) {
150	      console.error('WHATSAPP_APP_SECRET not configured');
151	      return false;
152	    }
153	
154	    const expectedSignature = createHmac('sha256', appSecret)
155	      .update(body)
156	      .digest('hex');
157	
158	    const trusted = Buffer.from(`sha256=${expectedSignature}`, 'ascii');
159	    const received = Buffer.from(signature, 'ascii');
160	
161	    return timingSafeEqual(trusted, received);
162	  } catch (error) {
163	    console.error('Webhook signature verification failed:', error);
164	    return false;
165	  }
166	}
